const ICON_NAMES={grid:'layout-dashboard',orders:'clipboard-list',finance:'wallet',supply:'package',factory:'building-factory-2',database:'database',shield:'shield-check',globe:'world',roadmap:'route',search:'search',arrow:'arrow-right',download:'download',play:'player-play',plus:'plus',clock:'clock',trend:'chart-line',check:'check',alert:'alert-triangle',refresh:'refresh',menu:'menu-2',link:'link',spark:'sparkles',users:'users',truck:'truck-delivery',layers:'stack-2',settings:'settings',bell:'bell',chevron:'chevron-down',collapse:'layout-sidebar-left-collapse',receipt:'receipt',building:'building',target:'target-arrow',quality:'rosette-discount-check',briefcase:'briefcase',calendar:'calendar',logout:'logout',folder:'folder',filter:'adjustments-horizontal',dots:'dots',moon:'moon',list:'list-details',lock:'lock'};
const icon=n=>`<i class="icon ti ti-${ICON_NAMES[n]||n}" aria-hidden="true"></i>`;
const nav=[['overview','经营总览','grid'],['orders','订单与渠道','orders'],['finance','财务中台','finance'],['supply','供应链协同','supply'],['production','研发与制造','factory'],['data','数据治理','database'],['compliance','合规与审计','shield'],['infrastructure','全球基础设施','globe'],['strategy','战略蓝图','roadmap']];
let route=location.hash.slice(1)||'overview';let filter='all';let period='month';let role='IT 总监';
const money=n=>'¥'+Number(n).toLocaleString('zh-CN',{maximumFractionDigits:2,minimumFractionDigits:2});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=(s,c='')=>`<span class="badge ${c}">${s}</span>`;
const btn=(s,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${s}</button>`;
function shell(){document.querySelector('#app').innerHTML=`<div class="shell"><div class="mobile-overlay" data-action="menu"></div><aside class="sidebar"><div class="brand"><div class="brandmark">D</div><div><strong>鼎匠 · 数智</strong><small>DINGJIANG ONE</small></div></div><div class="navlabel">BUSINESS WORKSPACE</div><nav>${nav.map((n,i)=>`${i===6?'<div class="navlabel">GOVERNANCE & STRATEGY</div>':''}<button class="navitem ${route===n[0]?'active':''}" data-route="${n[0]}">${icon(n[2])}<span>${n[1]}</span>${n[0]==='finance'?'<span class="count">2</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="workspace">${icon('globe')}<div>集团演示工作空间<small>深圳 · 全球业务协同</small></div></div><div class="side-foot">INTERVIEW EDITION · 2026<br>模拟业务数据 · 本机保存</div></div></aside><main class="main"><header class="topbar"><div class="crumb"><button class="menu-toggle" data-action="menu" aria-label="打开导航">${icon('menu')}</button><span>集团工作空间</span><span>/</span><strong>${nav.find(n=>n[0]===route)?.[1]||'经营总览'}</strong></div><div class="top-actions"><button class="search-trigger" data-action="search">${icon('search')} 搜索功能、订单或 SKU <kbd>⌘ K</kbd></button><span class="demo-tag">DEMO 演示环境</span><button data-action="guide" aria-label="演示指南">${icon('play')}</button><div class="role-wrap"><span class="avatar">IT</span><select class="role-select" id="role" aria-label="演示角色">${['IT 总监','财务经理','供应链经理','审计观察员'].map(x=>`<option ${x===role?'selected':''}>${x}</option>`).join('')}</select></div></div></header><div class="content" id="content"></div></main></div>`}
function head(title,en,desc,actions=''){return `<div class="pagehead"><div><div class="eyebrow">${en}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function kpis(items){return `<div class="kpis ${items.length===3?'small-kpis':''}">${items.map(x=>`<div class="kpi"><div class="kpi-label">${x[0]}${icon(x[4]||'trend')}</div><div class="kpi-value">${x[1]}<small>${x[2]||''}</small></div><div class="kpi-bottom">${x[3]}</div></div>`).join('')}</div>`}
function chart(){return '<div class="revenue-chart" id="revenue-chart" role="img" aria-label="收入趋势图"></div>'}
